INSERT INTO business_process_definition
(process_code,name,purpose,owner_name,trigger_description,outcome_description,version_number,status,technical_reference,process_type,parent_process_code,execution_scope,diagram_json,created_at,published_at)
SELECT 'quartzo-commercial-preparation-v1','Preparar operação comercial Quartzo','Preparar venda direta e entrega útil do kit digital com margem plausível.','Backend e agentes especializados','Quartzo e experimento identificados antes de divulgar.','Fontes e pareceres comprovados; ativação e mídia exigem homologação e autorização.',1,'PUBLISHED','docs/canonical/product-types-canon.v1.md','SUBPROCESS','pde-commercial-homologation-activation','PRODUCT','{"schemaVersion":"QUARTZO_COMMERCIAL_PREPARATION_V1","productTypeCode":"LOW_TICKET_DIGITAL_PRODUCT","nodes":[{"id":"start","type":"START","label":"Produto Quartzo e experimento identificados"},{"id":"entry","type":"TASK","label":"Preparar página de venda e prova real","owner":"Backend","description":"Vincular a publicação auditada do GeraSalesPage, preço, oferta, prova do kit e coletores; não exigir slot Opala."},{"id":"creative","type":"TASK","label":"Conferir criativo final aprovado","owner":"Backend","description":"Conferir a candidata final do anúncio, fiel ao kit e à oferta; imagem ou vídeo conforme o contrato do produto."},{"id":"checkout","type":"TASK","label":"Preparar checkout e contrato de entrega","owner":"Backend","description":"Vincular checkout auditado e conferir entrega, personalização, prazo, acesso e reembolso; pagamento simulado será comprovado no preflight."},{"id":"targeting","type":"TASK","label":"Conferir público aprovado por Atena","owner":"Backend","description":"Exigir público oficial aprovado e salvo no mesmo experimento."},{"id":"economics","type":"TASK","label":"Conferir margem e parecer de Plutus","owner":"Backend","description":"Reutilizar a revisão LIVE do plano financeiro da versão e seu parecer concluído; fonte ausente, custo incompleto, validade vencida ou margem inviável bloqueiam."},{"id":"humanExperienceReview","type":"TASK","label":"Homologar a experiência de compra e uso do kit","owner":"Psique","description":"Avaliar a página completa, prova real, esforço, desejo, compra, briefing quando aplicável, entrega e utilidade; nenhuma aprovação equivale a venda real.","responsibleAgentKeys":["customer-agent"]},{"id":"commercialIntegrityReview","type":"TASK","label":"Revisar integridade da oferta Quartzo","owner":"Têmis","description":"Conferir promessa, preço, anúncio, prova, checkout, direitos, personalização, entrega, suporte e métricas da mesma versão.","responsibleAgentKeys":["meta-ad-approver"]},{"id":"ready","type":"TASK","label":"Concluir preparação comercial Quartzo","owner":"Backend","description":"Revalidar insumos e pareceres, registrar prontidão e retornar ao pai; não ativar campanha nem alterar orçamento."},{"id":"end","type":"END","label":"Preparação comprovada; retornar à homologação e autorização"}],"flows":[{"id":"flow-0","from":"start","to":"entry"},{"id":"flow-1","from":"entry","to":"creative"},{"id":"flow-2","from":"creative","to":"checkout"},{"id":"flow-3","from":"checkout","to":"targeting"},{"id":"flow-4","from":"targeting","to":"economics"},{"id":"flow-5","from":"economics","to":"humanExperienceReview"},{"id":"flow-6","from":"humanExperienceReview","to":"commercialIntegrityReview"},{"id":"flow-7","from":"commercialIntegrityReview","to":"ready"},{"id":"flow-8","from":"ready","to":"end"}]}',UTC_TIMESTAMP(),UTC_TIMESTAMP()
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM business_process_definition WHERE process_code='quartzo-commercial-preparation-v1' AND version_number=1);

INSERT INTO business_process_definition
(process_code,name,purpose,owner_name,trigger_description,outcome_description,version_number,status,technical_reference,process_type,parent_process_code,execution_scope,diagram_json,created_at,published_at)
SELECT source.process_code,source.name,source.purpose,source.owner_name,source.trigger_description,source.outcome_description,8,'PUBLISHED',source.technical_reference,source.process_type,source.parent_process_code,source.execution_scope,'{"schemaVersion":"PDE_COMMERCIAL_HOMOLOGATION_ACTIVATION_V7","nodes":[{"id":"start","type":"START","label":"Produto e jornada aprovados","owner":"Backend","description":"O backend fixa produto, experimento, versão, tipo e ficha antes de preparar a operação."},{"id":"commercialPreparation","type":"TASK","label":"Preparar operação comercial conforme o tipo","owner":"Backend","description":"Seleciona pelo tipo cadastrado e pela ficha o subprocesso comercial aplicável, sem inferir pelo nome ou formato do produto.","commercialPreparationRouterVersion":"COMMERCIAL_PREPARATION_BY_PRODUCT_TYPE_V1","subprocessRoutes":[{"productTypeCode":"PDE","productTypeInternalName":"Opala","subprocessCode":"opala-commercial-preparation-v1","subprocessVersion":1},{"productTypeCode":"LOW_TICKET_DIGITAL_PRODUCT","productTypeInternalName":"Quartzo","subprocessCode":"quartzo-commercial-preparation-v1","subprocessVersion":1}]},{"id":"humanExperienceReview","type":"TASK","label":"Validar experiência e valor para o cliente","owner":"Psique","description":"Reutiliza o parecer de Psique produzido na preparação do mesmo produto, experimento, versão e configuração; mudança material exige renovação.","responsibilityDomain":"HUMAN_EXPERIENCE_REVIEW","reuseSubprocessActivityId":"humanExperienceReview","evidenceReuseVersion":"COMMERCIAL_REVIEW_REUSE_V1"},{"id":"commercialIntegrityReview","type":"TASK","label":"Validar integridade comercial","owner":"Têmis","description":"Reutiliza o parecer independente de Têmis da mesma preparação; divergência de anúncio, promessa, preço, checkout ou entrega bloqueia e retorna à origem.","responsibilityDomain":"COMMERCIAL_INTEGRITY_REVIEW","reuseSubprocessActivityId":"commercialIntegrityReview","evidenceReuseVersion":"COMMERCIAL_REVIEW_REUSE_V1"},{"id":"preflight","type":"TASK","label":"Executar homologação técnica do experimento","owner":"Backend","description":"Chama a homologação técnica para comprovar desktop, celular, compra simulada, acesso, entrega, falhas, eventos, segregação e limites, reutilizando evidências ainda vigentes.","subprocessCode":"experiment-homologation-activation"},{"id":"decision","type":"GATEWAY","label":"Preparação, experiência, integridade, técnica e economia estão válidas?","owner":"Backend","description":"Qualquer reprovação ou mudança material bloqueia a ativação e preserva a causa e a atividade responsável."},{"id":"authorization","type":"TASK","label":"Autorizar ativação, orçamento e janela","owner":"Operador humano","description":"Aprova explicitamente a versão, canais, teto financeiro, período e condições de parada; nenhum gate técnico concede gasto."},{"id":"end","type":"END","label":"Ativação autorizada","owner":"Backend","description":"O Processo 6 executa a operação; RUNNING depende da confirmação externa e dos gates de publicação."}],"flows":[{"id":"prepare-by-type","from":"start","to":"commercialPreparation"},{"id":"reuse-psique","from":"commercialPreparation","to":"humanExperienceReview"},{"id":"reuse-themis","from":"humanExperienceReview","to":"commercialIntegrityReview"},{"id":"technical-homologation","from":"commercialIntegrityReview","to":"preflight"},{"id":"commercial-gate","from":"preflight","to":"decision"},{"id":"approved","from":"decision","to":"authorization","label":"Todos os gates vigentes"},{"id":"authorized","from":"authorization","to":"end"},{"id":"rework-preparation","from":"decision","to":"commercialPreparation","label":"Corrigir causa na preparação","kind":"REWORK"},{"id":"rework-experience","from":"decision","to":"humanExperienceReview","label":"Renovar experiência afetada","kind":"REWORK"},{"id":"rework-integrity","from":"decision","to":"commercialIntegrityReview","label":"Renovar integridade afetada","kind":"REWORK"},{"id":"rework-technical","from":"decision","to":"preflight","label":"Renovar homologação afetada","kind":"REWORK"}]}',UTC_TIMESTAMP(),UTC_TIMESTAMP()
FROM business_process_definition source LEFT JOIN business_process_definition existing ON existing.process_code=source.process_code AND existing.version_number=8
WHERE source.process_code='pde-commercial-homologation-activation' AND source.version_number=7 AND existing.id IS NULL;

