INSERT INTO business_process_chain_definition
(chain_code,name,purpose,outcome_description,primary_metric,version_number,status,created_at,published_at)
SELECT source.chain_code,source.name,source.purpose,source.outcome_description,source.primary_metric,17,'PUBLISHED',UTC_TIMESTAMP(),UTC_TIMESTAMP()
FROM business_process_chain_definition source LEFT JOIN business_process_chain_definition existing ON existing.chain_code=source.chain_code AND existing.version_number=17
WHERE source.chain_code='pde-value-creation-delivery' AND source.version_number=16 AND existing.id IS NULL;

INSERT INTO business_process_chain_item
(chain_definition_id,process_definition_id,sequence_number,value_contribution,created_at)
SELECT target.id,CASE WHEN previous.process_code='pde-commercial-homologation-activation' THEN updated.id ELSE item.process_definition_id END,item.sequence_number,item.value_contribution,UTC_TIMESTAMP()
FROM business_process_chain_definition source
JOIN business_process_chain_item item ON item.chain_definition_id=source.id
JOIN business_process_definition previous ON previous.id=item.process_definition_id
JOIN business_process_definition updated ON updated.process_code='pde-commercial-homologation-activation' AND updated.version_number=8
JOIN business_process_chain_definition target ON target.chain_code=source.chain_code AND target.version_number=17
LEFT JOIN business_process_chain_item existing ON existing.chain_definition_id=target.id AND existing.sequence_number=item.sequence_number
WHERE source.chain_code='pde-value-creation-delivery' AND source.version_number=16 AND existing.id IS NULL;

UPDATE business_process_definition SET status='PUBLISHED' WHERE (process_code='quartzo-commercial-preparation-v1' AND version_number=1) OR (process_code='pde-commercial-homologation-activation' AND version_number=8);
UPDATE business_process_chain_definition SET status='PUBLISHED' WHERE chain_code='pde-value-creation-delivery' AND version_number=17;
